def get_robot_variable(var):
    # type: (str) -> Optional[str]
    """
    Return the given variable value from robot.

    :param var: name of variable
    :return: Value of variable and None if variable is not defined
    """
    try:
        return BuiltIn().get_variable_value("${{{}}}".format(var))
    except RobotNotRunningError:
        return None


def execute_in_parallel(task_list):
    # type: (List[Any]) -> List[Any]
    """
    Executes provided Tasks in parallel.
    Each object on tasks_list must be of Task type.

    :param task_list: list of Tasks to be executed
    :return: list with results
    """
    if not task_list:
        return []
    futures = []
    return_list = []
    with ThreadPoolExecutor(max_workers=len(task_list)) as executor:
        for task in task_list:
            future = executor.submit(task.run())
            for fn_callback in task.fn_callbacks:
                future.add_done_callback(fn_callback)
            futures.append(future)
        for future in as_completed(futures):
            return_list.append(future.result())
    return return_list


def run_remote_cmd(logger, user, host, passwd, cmd, priv_key="id_rsa", run_in_bg=False, timeout=10):
    # type: (Logger, str, str, str, str, str, bool, float) -> Tuple[str, str]
    """
    Run command at remote host and return command stdout and stderr.
    If command was run in background both stdout and stderr will be empty string.
    :param logger: network logger
    :param user: user name
    :param host: host name or host IP address
    :param passwd: user password (use for private key as well)
    :param cmd: command to run at remote host
    :param priv_key: private key filename in user .ssh directory, default id_rsa
    :param run_in_bg: if true command will be run in background, default False
    :param timeout: timeout to acquire ssh connection
    :return: tuple with command output and command errors
    """
    from mock import MagicMock

    logger = logger or MagicMock()
    try:
        with _get_ssh_connection(logger, host, user, passwd, priv_key, timeout=timeout) as ssh:
            if run_in_bg:
                channel = ssh.get_transport().open_session()
                cmd = cmd + " &"
                channel.exec_command(cmd)
                out, err = "", ""
            else:
                _, sout, serr = ssh.exec_command(cmd)
                out, err = sout.read().strip().decode("utf-8"), serr.read().strip().decode("utf-8")
            logger.debug(msg="Send to: {} command: {}".format(host, cmd))
        return out, err
    except (ssh_exception.NoValidConnectionsError, ssh_exception.SSHException) as err:
        logger.error("Copying files failed. SSH connection failure.")
        return "", str(err)


def skip_if_dryrun(fun):
    # type: (Callable) -> Callable
    """Simple decorator for robot dryrun"""

    def _inner(*args, **kwargs):
        if is_dry_run():
            return
        return fun(*args, **kwargs)

    return _inner


def is_dry_run():
    # type: () -> bool
    """
    Check if Robot is running in dryrun mode.
    If Robot isn't running False is return.

    :return: True if dryrun is active, False otherwise
    """
    dry_run = False
    try:
        from robot.running.context import EXECUTION_CONTEXTS

        curr_ctx = EXECUTION_CONTEXTS.current
        if curr_ctx:
            dry_run = curr_ctx.dry_run
    except Exception:
        pass
    return dry_run


class Singleton(type):
    """A singleton class."""

    _instances = {}

    def __call__(cls, *args, **kwargs):
        """Check if instance is created if yes, return it. Do not allow more instances."""
        if cls not in cls._instances:
            cls._instances[cls] = super(Singleton, cls).__call__(*args, **kwargs)
        return cls._instances[cls]


