def is_ip_addr(ip_addr):
    # type: (str) -> bool
    """Checks if provided IP address is correct."""
    if re.search(
        r"^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\.){3}"
        r"([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])$",
        ip_addr,
    ):
        return True
    return False


@contextmanager
def _get_ssh_connection(logger, host, user, passwd, priv_key="id_rsa", timeout=10):
    # type: (Logger, str, str, str, str, float) -> None
    """
    Context manager for ssh connection.

    :param logger: network logger
    :param host: host name or host IP address
    :param user: user name
    :param passwd: user password (use for private key as well)
    :param priv_key: private key filename in user .ssh directory, default id_rsa
    :param timeout: timeout to acquire ssh connection
    :return: ssh_connection
    """
    ssh = SSHClient()
    ssh.set_missing_host_key_policy(AutoAddPolicy())
    try:
        ssh.connect(
            hostname=host,
            username=user,
            password=passwd,
            key_filename=path.expanduser("~/.ssh/{}".format(priv_key)),
            timeout=timeout,
        )
        yield ssh
    except (ssh_exception.NoValidConnectionsError, ssh_exception.SSHException) as err:
        logger.debug(
            "SSH connection failed, please check IP and/or TL config "
            "(robotlte/config/<site>/<tl_name>/__init__.py). Error: {}".format(err)
        )
        raise
    except Exception as e:
        logger.debug("Exception: {}".format(e))
    finally:
        ssh.close()
        del ssh


class MySFTPClient(SFTPClient):
    """Simple SFTPClient to handle getting whole directories instead of single files"""

    def get_dir(self, source, target):
        # type: (str, str) -> None
        """
        Downloads the content of the source directory to the target path.
        The target directory needs to exists. All subdirectories in source are
        created under target.
        :param source: path of source directory
        :param target: path of target directory
        """
        for item in self.listdir(source):
            if S_ISREG(self.lstat(path.join(source, item)).st_mode):
                self.get(path.join(source, item), "{}/{}".format(target, item))
            else:
                try:
                    makedirs("{}/{}".format(target, item))
                except OSError:
                    pass
                self.get_dir(path.join(source, item), "{}/{}".format(target, item))


def copy_to_remote_location(logger, remote_host, remote_username, remote_password, local_path, remote_path):
    # type: (Logger, str, str, str, List[str], List[str]) -> None
    """
    Send list of file(s) to remote host with provided location.

    Both list should be the same length
    Both list should contain full path
    First element from local will be copied to first element of second

    :param logger: network logger
    :param remote_host: IP address of remote location
    :param remote_username: username for remote host
    :param remote_password: password for remote host
    :param local_path: list of full path on local machine
    :param remote_path: list of full path on remote machine
    """
    logger.debug(
        "remote_host = {}, local_path ({}) = {}, remote_path ({}) = {}".format(
            remote_host, len(local_path), local_path, len(remote_path), remote_path
        )
    )
    try:
        with _get_ssh_connection(logger, remote_host, remote_username, remote_password) as ssh:
            sftp = MySFTPClient.from_transport(ssh.get_transport())
            for file_path1, file_path2 in zip(local_path, remote_path):
                logger.debug("Host: {} local_path: {}".format(remote_host, local_path))
                attributes = sftp.put(file_path1, file_path2, confirm=True)
                logger.debug("Host: {} Attr: {} remote_path: {}".format(remote_host, attributes, file_path2))
    except (ssh_exception.NoValidConnectionsError, ssh_exception.SSHException):
        logger.error("Copying files failed. SSH connection failure.")


def copy_from_remote_location(logger, remote_host, remote_username, remote_password, local_path, remote_path):
    # type: (Logger, str, str, str, str, str) -> None
    """
    Get log from vmhost with provided location
    :param logger: network logger
    :param remote_host: IP address of remote location
    :param remote_username: username for remote host
    :param remote_password: password for remote host
    :param local_path: path on local machine where where to put logs
    :param remote_path: path on remote machine where logs are stored
    """
    logger.debug("remote_host = {}, local_path = {}, remote_path = {}".format(remote_host, local_path, remote_path))
    try:
        with _get_ssh_connection(logger, remote_host, remote_username, remote_password) as ssh:
            sftp = MySFTPClient.from_transport(ssh.get_transport())
            remote_location_st_mode = sftp.lstat(remote_path).st_mode
            if S_ISDIR(remote_location_st_mode):
                logger.debug("remote_host = {}, SERVER_HOST = {}".format(remote_host, OUTSIDE_IP))
                sftp.get_dir(remote_path, local_path)
            elif S_ISREG(remote_location_st_mode):
                file_name = path.split(remote_path)[-1]
                local_path = path.join(local_path, file_name)
                sftp.get(remote_path, local_path)
    except (ssh_exception.NoValidConnectionsError, ssh_exception.SSHException):
        logger.error("Copying files failed. SSH connection failure.")


def remove_in_remote_location(logger, remote_host, remote_username, remote_password, remote_path):
    # type: (Logger, str, str, str, List[str]) -> None
    """
    Remove list of file(s) from remote host.

    List should contain full path

    :param logger: network logger
    :param remote_host: IP address of remote location
    :param remote_username: username for remote host
    :param remote_password: password for remote host
    :param remote_path: list of full path on remote machine
    """
    logger.debug("remote_host = {}, remote_path ({}) = {}".format(remote_host, len(remote_path), remote_path))
    try:
        with _get_ssh_connection(logger, remote_host, remote_username, remote_password) as ssh:
            sftp = MySFTPClient.from_transport(ssh.get_transport())
            for file_path in remote_path:
                try:
                    sftp.remove(file_path)
                    logger.debug("Host: {} file: {}".format(remote_host, file_path))
                except (IOError, OSError) as err:
                    logger.debug("Error: {} @ Host: {} file: {}".format(err, remote_host, file_path))
    except (ssh_exception.NoValidConnectionsError, ssh_exception.SSHException):
        logger.error("Removing files failed. SSH connection failure.")


# <=><=><=><=><=><=><=><=><=><=><=><=> os tools <=><=><=><=><=><=><=><=><=><=><=><=>
def get_python_process_info_from_ps_output(
    process_name, process_cmd, shell=True, ps_flags="-ef", grep_flags="-iE", host_data=None
):
    # type: (str, str, bool, str, str, Optional[vm_host]) -> Generator[Match]
    """
    Returns python process info from ps for specified command
    :param process_name: name of process to find
    :param process_cmd: command to execute as list of parameters
    :param shell: whether process should be executed in new shell or not
    :param ps_flags: flags for 'ps' command
    :param grep_flags: flags for 'grep' command
    :param host_data: host param from where output should be taken. If provided then cmd is executed remotely
    :return: process as regexp object
    """
    ps_output, regexp_for_ps = _run_unix_cmd(grep_flags, process_cmd, ps_flags, shell, host_data)
    # todo switch to 'yield from' and extract to method when switchover to python 3.6
    for proc in regexp_for_ps.finditer(ps_output):
        ps_cmd = proc.group("CMD")
        if ps_cmd.find(process_name) != -1 and ps_cmd.find("grep") == -1:
            yield proc


def _run_unix_command_on_target(grep_flags, process_cmd, ps_flags, host_data=None, shell=False):
    cmd = 'ps {} | grep {} "{}"'.format(ps_flags, grep_flags, process_cmd)
    ps_output, err = "", ""
    if not host_data:
        ps_output = _get_output_of_unix_command(cmd=[cmd], shell=shell)
    else:
        ps_output, err = run_remote_cmd(None, host_data.usr, host_data.addr, host_data.passwd, cmd=cmd)
    return ps_output, err


def _get_regexp_for_ps_output(grep_flags, ps_flags):
    assert ps_flags.startswith("-"), "PS_flags does not start with `-` sign"
    assert grep_flags.startswith("-"), "grep_flags does not start with `-` sign"
    regexp_for_ps = re.compile(
        r"(?P<UID>\w+)\s+(?P<PID>\d+)\s+(?P<PPID>\d+)\s+(?P<C>\d+)\s+"
        r"(?P<SYSTIME>\S+)\s+(?P<TTY>\S+)\s+(?P<TIME>\S+)\s+(?P<CMD>.*)"
    )
    return regexp_for_ps


def _run_unix_cmd(grep_flags, process_cmd, ps_flags, shell=False, host_data=None):
    regexp_for_ps = _get_regexp_for_ps_output(grep_flags, ps_flags)
    ps_output, err = _run_unix_command_on_target(grep_flags, process_cmd, ps_flags, host_data, shell)
    return ps_output, regexp_for_ps


def get_python_process_pid_by_command(
    process_name, process_cmd, shell=True, ps_flags="-ef", grep_flags="-iE", host_data=None
):
    # type: (str, str, bool, str, str, Optional[vm_host]) -> int
    """
    Grep 'ps' command and returns PID of process or 0 if nothing found.

    :param process_name: name of process to be found
    :param process_cmd: command to execute as list of parameters
    :param shell: whether process should be executed in new shell or not
    :param ps_flags: flags for 'ps' command
    :param grep_flags: flags for 'grep' command
    :param host_data: host param from where output should be taken. If provided then cmd is executed remotely
    :return: PID or 0 if nothing found
    """
    for proc in get_python_process_info_from_ps_output(
        process_name, process_cmd, shell, ps_flags, grep_flags, host_data
    ):
        return int(proc.group("PID"))
    return 0


def _get_output_of_unix_command(cmd, shell=True):
    # type: (list, bool) -> str
    """
    Return unix command output.
    :param cmd: command to execute as list with separated arguments
    :param shell: whether process should be executed in new shell or not
    :return: full command output
    """
    out = check_output(cmd, shell=shell)
    try:
        out = out.decode("utf-8")
    except Exception:
        # todo: catch ValueError, UnicodeError or UnicodeDecodeError only???
        pass
    return out


def kill_process_by_pid(pid, signal_number=9, host_data=None):
    # type: (int, int, Optional[vm_host]) -> None
    """
    Brutal force kill of process. Does nothing if PID <= 1 - no point of trying to kill PID == 1.
    :param pid: PID of process to kill
    :param signal_number: number of signal which should be used to kill process, by default SIGKILL(9)
    :param host_data: host param from where output should be taken. If provided then cmd is executed remotely
    """
    if pid > 1:
        if not host_data:
            kill(pid, signal_number)
        else:
            cmd = "sudo kill -{} {}".format(signal_number, pid)
            run_remote_cmd(None, host_data.usr, host_data.addr, host_data.passwd, cmd)


def kill_all_processes_containing_name(logger, process_name, signal_number=9):
    # type: (Logger, str, int) -> None
    """
    All processes with specified name are killed.

    :param logger: network logger
    :param process_name: fragment of process name to be killed
    :param signal_number: number of signal which should be used to kill process, by default SIGKILL(9)
    """
    ps_cmd = "ps -eo '%p %a'"
    grep = "grep"
    cmd = ["{ps} | {g} {name} | {g} -v {g}".format(ps=ps_cmd, name=process_name, g=grep)]
    try:
        ps_output = _get_output_of_unix_command(cmd)
        for line_with_process in ps_output.splitlines():
            proc_info = line_with_process.split()
            pid = int(proc_info.pop(0))
            proc_cmd_args = " ".join(proc_info)

            kill_process_by_pid(pid, signal_number)
            logger.debug("Process killed:\nPID: {} INFO: {}".format(pid, proc_cmd_args))

    except CalledProcessError:
        logger.debug("There are no processes which name's includes >{}<. No killing this time.".format(process_name))


# <=><=><=><=><=><=><=><=><=><=><=><=> file system tools <=><=><=><=><=><=><=><=><=><=><=><=>
def get_filenames_containing_string(logger, _path, pattern="*"):
    # type: (Logger, str, str) -> List[str]
    """
    Search through filenames and return matching ones.
    Asterisk <*> can be used as wildcard.
    Matching hidden files with '.' a dot is disabled.

    :param logger: network logger
    :param _path: to folder with files
    :param pattern: to be searched in filenames
    """
    _slash = "/"
    if not _path.endswith(_slash):
        _path += _slash

    dir_and_file = "{p}{s}".format(p=_path, s=pattern)
    result = glob(dir_and_file)
    logger.debug("Searching for {} result {}".format(dir_and_file, result))
    return result


def delete_files(logger, files):
    # type: (Logger, List[str]) -> None
    """
    Delete files.

    :param logger: network logger
    :param files: to be deleted
    """
    if isinstance(files, str):
        files = [files]

    for file_to_del in files:
        try:
            remove(file_to_del)
            logger.debug("File {} removed.".format(file_to_del))
        except OSError as err:
            logger.warning("Cannot remove file {} due to error: \n{}".format(file_to_del, err))


def move_logs_to_specified_directory(logger, dst_path, src_path, regex="*"):
    # type: (Logger, str, str, str) -> None
    """
    Move files and whole directories recursively between directories.
    Optionally specify regex to match certain files.

    :param logger: network logger
    :param dst_path: to be copied to
    :param src_path: to be copied from
    :param regex: filter filenames; greedy if not specified
    """
    fn = get_filenames_containing_string(logger, src_path, regex)
    try:
        for file_or_directory in fn:
            move(file_or_directory, dst_path)
        logger.debug("Moved {n} files from {s} to {d}".format(n=len(fn), s=src_path, d=dst_path))
    except (OSError, IOError, Error) as err:
        logger.error("Failed to move {f} to: {d} Error: {e}".format(f=file_or_directory, d=dst_path, e=err))


def file_exists(fpath):
    # type: (str) -> bool
    """
    Check if file exists.

    :param fpath: path to file
    """
    return path.isfile(fpath)


def copy_file(logger, src, dst):
    # type: (Logger, str, str) -> bool
    """
    Copy file to destination directory. Catch OSError.
    :param logger: network logger
    :param src: path to file
    :param dst: destination path for file
    :return: True if success, False otherwise
    """
    try:
        copy(src, dst)
        logger.debug("Copied file {} to: {}".format(src, dst))
        return True
    except (IOError, OSError) as e:
        logger.error("Cannot copy file {} because of error: {}".format(src, e))
        return False


def change_file_permissions(logger, filename, perm):
    # type: (Logger, str, int) -> None
    """
    Change file permisssions.
    :param logger: network logger
    :param filename: path to file
    :param perm: wanted permissions like 0o755
    """
    try:
        chmod(filename, perm)
        logger.debug("Changed permissions of file: {}".format(filename))
    except OSError as e:
        logger.error("Unable to change permissions of file {} due to error: {}".format(filename, e))
        raise


